INSERT INTO public.projects VALUES ('50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000010', '50000000-0000-4000-8000-000000000011', '50000000-0000-4000-8000-000000000013', '50000000-0000-4000-8000-000000000014'), ('50000000-0000-4000-8000-000000000017', '50000000-0000-4000-8000-000000000010', '50000000-0000-4000-8000-000000000011', '50000000-0000-4000-8000-000000000013', '50000000-0000-4000-8000-000000000014');
INSERT INTO public.project_team_members VALUES ('50000000-0000-4000-8000-000000000018', '50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000014');
