INSERT INTO public.drive_node_revisions VALUES ('50000000-0000-4000-8000-000000000023', '50000000-0000-4000-8000-000000000020', 3), ('50000000-0000-4000-8000-000000000024', '50000000-0000-4000-8000-000000000021', 2), ('50000000-0000-4000-8000-000000000025', '50000000-0000-4000-8000-000000000022', 1);
INSERT INTO public.document_control_registers VALUES ('50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000020', '50000000-0000-4000-8000-000000000016', 'APPROVED', 3), ('50000000-0000-4000-8000-000000000027', '50000000-0000-4000-8000-000000000021', '50000000-0000-4000-8000-000000000016', 'APPROVED', 2), ('50000000-0000-4000-8000-000000000028', '50000000-0000-4000-8000-000000000022', '50000000-0000-4000-8000-000000000017', 'APPROVED', 1);
SELECT set_config('request.jwt.claim.sub', '50000000-0000-4000-8000-000000000001', false);
CREATE TEMP TABLE first_submit AS SELECT * FROM public.submit_project_deviation('50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000023', '{"reason":"Supplier material differs","risk":"Heat drift","safeguards":"Incoming inspection","customerImpact":false,"affectedPartReference":"R7","affectedRevisionReference":"B","affectedQuantity":25}'::jsonb, '[{"documentRegisterId":"50000000-0000-4000-8000-000000000027","documentRevisionId":"50000000-0000-4000-8000-000000000024"}]'::jsonb, '50000000-0000-4000-8000-000000000090');
DO $$ BEGIN
  IF (SELECT count(*) FROM first_submit) <> 1 OR (SELECT replayed FROM first_submit) THEN RAISE EXCEPTION 'Expected one proposed deviation submission'; END IF;
  IF (SELECT count(*) FROM public.project_deviation_submissions) <> 1 OR (SELECT count(*) FROM public.project_deviation_submission_revisions) <> 1 OR (SELECT count(*) FROM public.project_deviation_submission_evidence) <> 1 OR (SELECT count(*) FROM public.project_deviation_submission_audit_events) <> 1 OR (SELECT count(*) FROM public.project_deviation_submission_request_receipts) <> 1 THEN RAISE EXCEPTION 'Expected immutable deviation header revision evidence audit and receipt'; END IF;
  IF (SELECT status FROM public.project_deviation_submissions) <> 'PROPOSED_SUBMITTED' THEN RAISE EXCEPTION 'Unexpected approval state'; END IF;
END $$;
CREATE TEMP TABLE exact_replay AS SELECT * FROM public.submit_project_deviation('50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000023', '{"affectedQuantity":25,"affectedRevisionReference":"B","affectedPartReference":"R7","customerImpact":false,"safeguards":"Incoming inspection","risk":"Heat drift","reason":"Supplier material differs"}'::jsonb, '[{"documentRevisionId":"50000000-0000-4000-8000-000000000024","documentRegisterId":"50000000-0000-4000-8000-000000000027"}]'::jsonb, '50000000-0000-4000-8000-000000000090');
DO $$ BEGIN
  IF NOT (SELECT replayed FROM exact_replay) OR (SELECT deviation_submission_id FROM exact_replay) <> (SELECT deviation_submission_id FROM first_submit) THEN RAISE EXCEPTION 'Exact replay did not return persisted deviation'; END IF;
  BEGIN PERFORM * FROM public.submit_project_deviation('50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000023', '{"reason":"Changed","risk":"Heat drift","safeguards":"Incoming inspection","customerImpact":false,"affectedPartReference":"R7","affectedRevisionReference":"B","affectedQuantity":25}'::jsonb, '[{"documentRegisterId":"50000000-0000-4000-8000-000000000027","documentRevisionId":"50000000-0000-4000-8000-000000000024"}]'::jsonb, '50000000-0000-4000-8000-000000000090'); RAISE EXCEPTION 'Changed replay was accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Request key conflicts%' THEN RAISE; END IF; END;
  BEGIN PERFORM * FROM public.submit_project_deviation('50000000-0000-4000-8000-000000000017', '50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000023', '{"reason":"Cross project","risk":"Risk","safeguards":"Guard","customerImpact":false,"validFrom":"2026-10-11","validUntil":"2026-10-12"}'::jsonb, '[{"documentRegisterId":"50000000-0000-4000-8000-000000000027","documentRevisionId":"50000000-0000-4000-8000-000000000024"}]'::jsonb, '50000000-0000-4000-8000-000000000091'); RAISE EXCEPTION 'Cross project source was accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Deviation submission requires%' THEN RAISE; END IF; END;
  BEGIN PERFORM * FROM public.submit_project_deviation('50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000023', '{"reason":"Bad scope","risk":"Risk","safeguards":"Guard","customerImpact":false}'::jsonb, '[{"documentRegisterId":"50000000-0000-4000-8000-000000000027","documentRevisionId":"50000000-0000-4000-8000-000000000024"}]'::jsonb, '50000000-0000-4000-8000-000000000092'); RAISE EXCEPTION 'Missing validity or part scope was accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Deviation payload requires exactly%' THEN RAISE; END IF; END;
  BEGIN PERFORM * FROM public.submit_project_deviation('50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000023', '{"reason":"Inverted","risk":"Risk","safeguards":"Guard","customerImpact":false,"validFrom":"2026-10-12","validUntil":"2026-10-11"}'::jsonb, '[{"documentRegisterId":"50000000-0000-4000-8000-000000000027","documentRevisionId":"50000000-0000-4000-8000-000000000024"}]'::jsonb, '50000000-0000-4000-8000-000000000093'); RAISE EXCEPTION 'Inverted validity was accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Deviation validity period is inverted%' THEN RAISE; END IF; END;
  BEGIN PERFORM * FROM public.submit_project_deviation('50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000023', '{"reason":"Bad evidence","risk":"Risk","safeguards":"Guard","customerImpact":false,"validFrom":"2026-10-11","validUntil":"2026-10-12"}'::jsonb, '[{"documentRegisterId":"50000000-0000-4000-8000-000000000028","documentRevisionId":"50000000-0000-4000-8000-000000000025"}]'::jsonb, '50000000-0000-4000-8000-000000000094'); RAISE EXCEPTION 'Cross project evidence was accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Deviation evidence requires%' THEN RAISE; END IF; END;
END $$;
SELECT set_config('request.jwt.claim.sub', '50000000-0000-4000-8000-000000000002', false);
DO $$ BEGIN BEGIN PERFORM * FROM public.submit_project_deviation('50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000023', '{"reason":"Unauthorized","risk":"Risk","safeguards":"Guard","customerImpact":false,"validFrom":"2026-10-11","validUntil":"2026-10-12"}'::jsonb, '[{"documentRegisterId":"50000000-0000-4000-8000-000000000027","documentRevisionId":"50000000-0000-4000-8000-000000000024"}]'::jsonb, '50000000-0000-4000-8000-000000000095'); RAISE EXCEPTION 'Unauthorized actor was accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Deviation submission requires%' THEN RAISE; END IF; END; END $$;
SELECT set_config('request.jwt.claim.sub', '50000000-0000-4000-8000-000000000001', false);
INSERT INTO public.deviation_test_failpoints VALUES ('project_deviation_submission_request_receipts', true);
DO $$ DECLARE before_headers integer; before_revisions integer; before_evidence integer; before_audits integer; before_receipts integer; BEGIN
  SELECT count(*) INTO before_headers FROM public.project_deviation_submissions; SELECT count(*) INTO before_revisions FROM public.project_deviation_submission_revisions; SELECT count(*) INTO before_evidence FROM public.project_deviation_submission_evidence; SELECT count(*) INTO before_audits FROM public.project_deviation_submission_audit_events; SELECT count(*) INTO before_receipts FROM public.project_deviation_submission_request_receipts;
  BEGIN PERFORM * FROM public.submit_project_deviation('50000000-0000-4000-8000-000000000016', '50000000-0000-4000-8000-000000000026', '50000000-0000-4000-8000-000000000023', '{"reason":"Rollback","risk":"Risk","safeguards":"Guard","customerImpact":false,"validFrom":"2026-10-11","validUntil":"2026-10-12"}'::jsonb, '[{"documentRegisterId":"50000000-0000-4000-8000-000000000027","documentRevisionId":"50000000-0000-4000-8000-000000000024"}]'::jsonb, '50000000-0000-4000-8000-000000000096'); RAISE EXCEPTION 'Rollback failpoint was accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Injected deviation test failure%' THEN RAISE; END IF; END;
  IF (SELECT count(*) FROM public.project_deviation_submissions) <> before_headers OR (SELECT count(*) FROM public.project_deviation_submission_revisions) <> before_revisions OR (SELECT count(*) FROM public.project_deviation_submission_evidence) <> before_evidence OR (SELECT count(*) FROM public.project_deviation_submission_audit_events) <> before_audits OR (SELECT count(*) FROM public.project_deviation_submission_request_receipts) <> before_receipts THEN RAISE EXCEPTION 'Receipt failure did not roll back every deviation record'; END IF;
END $$;
ROLLBACK;